solutionCode:
pub struct Ponto {
    pub x: i32,
    pub y: i32,
}

pub fn ponto_de(x: i32, y: i32) -> Ponto {
    Ponto { x: x, y: y }
}

impl Ponto {
    pub fn area(&self) -> i32 {
        self.x * self.y
    }
}

testsCode:
use desafio::ponto_de;

#[test]
fn testa_a_area_do_ponto_dois_por_tres() {
    assert_eq!(ponto_de(2, 3).area(), 6);
}

#[test]
fn testa_a_area_do_ponto_quatro_por_cinco() {
    assert_eq!(ponto_de(4, 5).area(), 20);
}
